// Carves @adyen/* out of PWA Kit's default `vendor` cache group, which forces every
// node_modules package into one shared chunk regardless of static/dynamic import — see
// @salesforce/pwa-kit-dev/configs/webpack/config.js's `withChunking` (`chunks: 'all'`, a
// fixed `name: 'vendor'`). Adyen is only ever reached from already-lazy-loaded routes
// (Checkout, CheckoutRedirect, CheckoutConfirmation), so isolating it into its own chunk
// here means it downloads only on checkout, not on every page. `priority` must beat the
// default vendor group's implicit 0 or this group never wins the match.
const configs = require('@salesforce/pwa-kit-dev/configs/webpack/config');

const client = configs.find((config) => config.name === 'client');

if (client) {
  client.optimization.splitChunks.cacheGroups.adyen = {
    test: (module) => Boolean(module?.context) && /node_modules[\\/]@adyen[\\/]/.test(module.context),
    name: 'adyen',
    chunks: 'all',
    priority: 10,
  };
}

module.exports = configs;

