import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmAccordion } from 'app/components/ui-kits/atoms/zimmAccordion';
import type { ZimmAccordionItem } from 'app/components/ui-kits/atoms/zimmAccordion';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';

const ZIMM_FILTERS_DRAWER_CONTENT_RECIPE = 'ZimmFiltersDrawerContent';

/**
 * A single filter facet group as it appears inside the drawer — a labelled accordion whose
 * expanded panel holds the concrete facet UI (radio-button list, colour swatches, size
 * chips). SFCC-847 supplies the container; the panel content comes from the caller and, in
 * production, is built by SFCC-108.
 */
export type FilterFacetGroup = ZimmAccordionItem;

type ZimmFiltersDrawerContentProps = {
  facetGroups: FilterFacetGroup[];
  /** Which facet group is open on first render. Uncontrolled — the user can toggle from here
   *  on without informing the parent. */
  initialExpandedId?: string;
  /** Fired when the shopper presses CLEAR. This organism holds no filter state; the caller
   *  owns the reset. */
  onClear: () => void;
  /** Fired when the shopper presses APPLY. Same caller-owns-state note as onClear. */
  onApply: () => void;
  /** Overridable button copy — defaults suit AU English. */
  clearLabel?: string;
  applyLabel?: string;
};

/**
 * SFCC-847 drawer/content/filters — the panel content passed as children into ZimmDrawer.
 * Composes ZimmAccordion (single-open facet-group list) with a recipe-styled footer
 * carrying CLEAR (Secondary) and APPLY (Primary).
 *
 * The drawer shell, overlay, slide-in behaviour, and close trigger are owned by ZimmDrawer
 * (SFCC-736 — In SIT). Each facet group's *inner* content (radio/checkbox/swatch UI) is
 * SFCC-108's scope and is supplied by the caller via `facetGroups[i].content`.
 *
 * `size="large"` on the CLEAR/APPLY buttons resolves to 52px via `zimmButton.css.ts`
 * (`--zimm-size-action-height-lg`), matching Figma. An earlier version of this file's
 * docblock warned about a stale `BTN_HEIGHT_LG=50px` per overrideStyling.md — confirmed
 * 2026-09-16 that the recipe already ships 52px; the doc note is out of date.
 *
 * @param props see ZimmFiltersDrawerContentProps
 */
export const ZimmFiltersDrawerContent = ({
  facetGroups,
  initialExpandedId,
  onClear,
  onApply,
  clearLabel = 'CLEAR',
  applyLabel = 'APPLY',
}: ZimmFiltersDrawerContentProps) => {
  const styles = useMultiStyleConfig(ZIMM_FILTERS_DRAWER_CONTENT_RECIPE, {});

  return (
    <chakra.div sx={styles.root}>
      <chakra.div sx={styles.body}>
        <ZimmAccordion items={facetGroups} defaultExpandedId={initialExpandedId} />
      </chakra.div>
      <chakra.div sx={styles.footer}>
        <ZimmButton variant="secondary" size="large" label={clearLabel} onClick={onClear} fullWidth />
        <ZimmButton variant="primary" size="large" label={applyLabel} onClick={onApply} fullWidth />
      </chakra.div>
    </chakra.div>
  );
};

import { useLayoutEffect, useState } from 'react';

export type PendingRefinements = Record<string, string[]>;

type UseFilterDrawerStateParams = {
  /** Whether the filter drawer is currently open — pending state resyncs from the
   *  currently-applied filters every time this transitions to true. */
  isOpen: boolean;
  /** The category currently applied to the page (from the route), used as the initial
   *  pending category selection. */
  categoryId?: string;
  /** The currently-applied refinements — pass searchParams.refine (the real URL-derived
   *  ground truth), NOT productSearchResult.selectedRefinements (the SFCC API field that
   *  only reflects what the backend chose to echo back, which is often incomplete).
   *  Values may be a pipe-separated string ('Black|White'), an array, or a number. */
  selectedRefinements?: Record<string, string | number | (string | number)[] | undefined>;
};

type UseFilterDrawerStateReturn = {
  pendingCategoryId: string | undefined;
  setPendingCategoryId: (categoryId: string | undefined) => void;
  pendingRefine: PendingRefinements;
  setValues: (attributeId: string, values: string[]) => void;
  removeValue: (attributeId: string, value: string) => void;
  clearAll: () => void;
  /** Re-derives pendingRefine from a (possibly different) selectedRefinements snapshot —
   *  same parsing the drawer-open resync uses. For a caller that reverts a pending category
   *  change back to the currently-applied category (e.g. removing the category chip): that
   *  category change already cleared pendingRefine via clearAll, so reverting it must also
   *  restore whatever refine is actually still applied, not leave the buffer empty. */
  resyncPendingRefine: (selectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => void;
};

/**
 * Parses a searchParams.refine-shaped object into the buffered PendingRefinements shape —
 * split out so both the drawer-open resync effect and a caller-triggered resync
 * (resyncPendingRefine) share one implementation.
 */
const parseSelectedRefinements = (
  selectedRefinements: UseFilterDrawerStateParams['selectedRefinements'],
): PendingRefinements => {
  const initial: PendingRefinements = {};
  Object.entries(selectedRefinements ?? {}).forEach(([attributeId, rawValue]) => {
    if (attributeId === 'cgid' || rawValue == null) return;
    // searchParams.refine values can be arrays (from buildAppliedRefine), pipe-separated
    // strings ('Black|White' — SFCC URL encoding), or plain numbers. Handle all three so
    // the resync works correctly regardless of whether the value was round-tripped through
    // the URL parser or set directly.
    const values: string[] = Array.isArray(rawValue) ? rawValue.map(String) : String(rawValue).split('|');
    if (values.length > 0 && values[0] !== '') initial[attributeId] = values;
  });
  return initial;
};

/**
 * Buffers SFCC-847 filter-drawer selections (category + every refinement facet) in local
 * state instead of applying each click straight to the URL/product grid. Resyncs from the
 * page's currently-applied filters every time the drawer opens, so a value chosen and then
 * abandoned (drawer closed without pressing APPLY) never reaches the URL, and reopening
 * after a previous APPLY reflects reality rather than stale local state.
 *
 * @returns pending category/refinement selections plus mutators. The caller is responsible
 * for actually applying them (navigating) when the shopper presses APPLY.
 */
export const useFilterDrawerState = ({
  isOpen,
  categoryId,
  selectedRefinements,
}: UseFilterDrawerStateParams): UseFilterDrawerStateReturn => {
  const [pendingCategoryId, setPendingCategoryId] = useState<string | undefined>(categoryId);
  const [pendingRefine, setPendingRefine] = useState<PendingRefinements>({});

  // useLayoutEffect (not useEffect) — runs synchronously after DOM commit and before the
  // browser paints. This prevents the visible flash of stale checkbox state that useEffect
  // causes: with useEffect the drawer renders once with the previous pendingRefine (user
  // briefly sees wrong checked state), then the effect fires and corrects it. The filter
  // drawer is always closed during SSR so the isOpen guard means this body never runs
  // server-side — the layout-effect SSR warning does not apply here.
  useLayoutEffect(() => {
    if (!isOpen) return;
    setPendingRefine(parseSelectedRefinements(selectedRefinements));
    setPendingCategoryId(categoryId);
    // Resync is keyed on `isOpen` alone. `categoryId`/`selectedRefinements` change on every
    // navigation — including the one APPLY itself triggers — so including them here would
    // re-run this effect right after APPLY and stomp the just-applied selection straight
    // back to whatever the next render resolves it to.
  }, [isOpen]);

  const resyncPendingRefine = (nextSelectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => {
    setPendingRefine(parseSelectedRefinements(nextSelectedRefinements));
  };

  const setValues = (attributeId: string, values: string[]) => {
    setPendingRefine((prev) => {
      if (values.length === 0) {
        const { [attributeId]: _removed, ...rest } = prev;
        return rest;
      }
      return { ...prev, [attributeId]: values };
    });
  };

  const removeValue = (attributeId: string, value: string) => {
    setPendingRefine((prev) => {
      const next = (prev[attributeId] ?? []).filter((v) => v !== value);
      if (next.length === 0) {
        const { [attributeId]: _removed, ...rest } = prev;
        return rest;
      }
      return { ...prev, [attributeId]: next };
    });
  };

  const clearAll = () => setPendingRefine({});

  return {
    pendingCategoryId,
    setPendingCategoryId,
    pendingRefine,
    setValues,
    removeValue,
    clearAll,
    resyncPendingRefine,
  };
};

export type AppliedRefine = Record<string, string | number | (string | number)[]>;

/**
 * Merges buffered facet selections into the page's real `searchParams.refine` object —
 * the pure computation behind the drawer's APPLY handler, split out so it's testable
 * without a component or navigation. Every attribute this drawer manages (every non-cgid
 * attributeId SFCC currently returns as a refinement) is fully overwritten from
 * `pendingRefine` — including being deleted if the shopper unticked it back to empty —
 * while any attribute this drawer does not manage (e.g. StoreInventoryFilter's `ilids`) is
 * left exactly as it was in `currentRefine`.
 *
 * @returns a new refine object; never mutates `currentRefine`.
 */
export const buildAppliedRefine = (
  currentRefine: AppliedRefine,
  managedAttributeIds: string[],
  pendingRefine: PendingRefinements,
): AppliedRefine => {
  const nextRefine: AppliedRefine = { ...currentRefine };
  managedAttributeIds.forEach((attributeId) => {
    delete nextRefine[attributeId];
  });
  Object.entries(pendingRefine).forEach(([attributeId, values]) => {
    nextRefine[attributeId] = values;
  });
  return nextRefine;
};

