import React from 'react';
import { useIntl } from 'react-intl';
import { Box, Checkbox, Flex, Stack, Text } from '@chakra-ui/react';
import { cssColorGroups } from '@salesforce/retail-react-app/app/constants';
// SFCC-847 — same ARIA-label messages OOTB's own CheckboxRefinements uses, reused verbatim
// rather than redefining equivalent strings.
import {
  ADD_FILTER,
  REMOVE_FILTER,
} from '@salesforce/retail-react-app/app/pages/product-list/partials/refinements-utils';
import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';

type ZimmCheckboxRefinementsProps = {
  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
  selectedFilters: string[];
  /** Renders the coarse cssColorGroups swatch dot (interim — see this component's own
   *  docblock) next to the label. Only meaningful for the colour attribute. */
  showColorSwatch?: boolean;
};

/**
 * SFCC-847 — near-identical to OOTB's own CheckboxRefinements
 * (`@salesforce/retail-react-app/app/pages/product-list/partials/checkbox-refinements.jsx`)
 * — same `toggleFilter` contract, same "hide a value that would return zero results unless
 * it's already selected" rule (PLP PRD §5.2 / SPR-20), same plain ADD_FILTER/REMOVE_FILTER
 * aria-label (no hit count — the drawer's design (Figma reference 2026-09-14) shows no
 * visible count next to any value, matching OOTB's own convention of only using the
 * HIT_COUNT message variants where the count is actually rendered).
 *
 * Adds an optional colour-family swatch dot (`showColorSwatch`), using OOTB's own coarse
 * `cssColorGroups` bucket-colour fallback — interim only: PLP PRD §5.4 (SPR-26)'s real
 * per-value swatch/pattern-image mapping in Business Manager is still Open/unconfirmed.
 *
 * @param props see ZimmCheckboxRefinementsProps
 */
export const ZimmCheckboxRefinements = ({
  filter,
  toggleFilter,
  selectedFilters,
  showColorSwatch = false,
}: ZimmCheckboxRefinementsProps) => {
  const intl = useIntl();
  return (
    <Stack spacing={1}>
      {filter.values?.map((value) => {
        const isChecked = selectedFilters.includes(String(value.value));
        // PLP PRD §5.2 (SPR-20): hide a value that would return zero results, unless it's
        // already selected (an actively-applied filter must stay visible/removable).
        if (value.hitCount === 0 && !isChecked) return null;
        const swatchColor = value.presentationId ? cssColorGroups[value.presentationId.toLowerCase()] : undefined;
        return (
          <Box key={String(value.value)}>
            <Checkbox
              isChecked={isChecked}
              onChange={() => toggleFilter(value, filter.attributeId, isChecked)}
              aria-label={intl.formatMessage(isChecked ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
              sx={{
                paddingLeft: 'var(--zimm-scale-3xs)',
                // Chakra paints the box on the `__control` part, so every visual override has
                // to target it. The same rules on the Checkbox root silently do nothing — the
                // label has no visible border, which is why the previous root-level
                // `_checked.borderColor` left the box rendering Chakra's default blue.
                '.chakra-checkbox__control': {
                  borderColor: 'var(--zimm-color-border-default)',
                  // Selected reads as a primary action, matching ZimmButton/ZimmSelectedChip.
                  _checked: {
                    background: 'var(--zimm-color-action-primary-bg-default)',
                    borderColor: 'var(--zimm-color-action-primary-bg-default)',
                    color: 'var(--zimm-color-action-primary-text)',
                  },
                  // Brand focus ring rather than `outline: none` — dropping the indicator
                  // entirely would fail WCAG 2.2 AA SC 2.4.7. Chakra's `_focusVisible` expands
                  // to `:focus-visible, [data-focus-visible]`, and it sets the latter on the
                  // control during keyboard focus, so this is the part that actually matches.
                  // No outline-offset here (unlike zimmLink/zimmButton): at this control's
                  // 16px size a detached ring reads far heavier than it does on a text link,
                  // so it sits flush to the box edge instead.
                  _focusVisible: {
                    outline: 'var(--zimm-focus-ring)',
                    outlineOffset: 0,
                    boxShadow: 'none',
                  },
                },
              }}
            >
              <Flex align="center" gap="var(--zimm-scale-2xs)">
                {showColorSwatch && (
                  <Box
                    boxSize="var(--zimm-icon-size-sm)"
                    borderRadius="full"
                    border="var(--zimm-border-width-default) solid var(--zimm-color-border-default)"
                    flexShrink={0}
                    background={swatchColor ?? 'transparent'}
                  />
                )}
                <Text as="span" textStyle="navigation">
                  {value.label}
                </Text>
              </Flex>
            </Checkbox>
          </Box>
        );
      })}
    </Stack>
  );
};

