import React from 'react';
import { Box, Flex, Stack, Text } from '@chakra-ui/react';
import { useIntl } from 'react-intl';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import {
  ADD_FILTER,
  REMOVE_FILTER,
} from '@salesforce/retail-react-app/app/pages/product-list/partials/refinements-utils';
import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';

type ZimmSizeRefinementsProps = {
  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
  selectedFilters: string[];
};

// Figma-exact chip width (node 40003890:151757) — the OOTB grid used a fixed 44px column.
// Treated as a MINIMUM, not a fixed size: see the layout note on SizeChipRow below.
// The 40px height is not here: it comes from ZimmButton's `size="medium"` recipe entry
// (--zimm-size-action-height-md), which matches the same Figma spec.
// audit-allow: Figma-sourced chip width with no equivalent --zimm-* token.
const CHIP_MIN_WIDTH = '89.3px';

/**
 * One flat row of size chips, styled to the Figma chip spec (node 40003890:151757) via
 * ZimmButton's primary/secondary variants.
 *
 * Flex-wrap rather than a grid, deliberately. Figma assumes short labels (0P, 1, S, 36), and a
 * fixed 89.3px track fits those exactly — but SFCC returns labels the spec never accounted for,
 * e.g. "One Size Fits All" (needs 92.1px of text against a 49.3px content box, so it spilled
 * straight out of the chip) and "0P (US 2P)". A grid can't solve this: its columns are uniform,
 * so widening the track to fit the longest label would inflate every chip. Flex sizes each chip
 * independently — CHIP_MIN_WIDTH holds the design for the common case while a long label grows
 * only its own chip.
 *
 * The real fix is upstream: these labels should be short (the design shows "ONE SIZE"), which is
 * BM/AP21 configuration, not front-end. This keeps the UI intact until that lands.
 */
const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeRefinementsProps) => {
  const intl = useIntl();

  return (
    <Flex wrap="wrap" gap="var(--zimm-scale-m)" marginTop="var(--zimm-scale-2xs)">
      {filter.values?.map((value) => {
        // Note the loose comparison, for "string == number" checks.
        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
        // Don't display refinements with no results, unless we got there by selecting too
        // many refinements
        if (value.hitCount === 0 && !isSelected) return null;

        return (
          <ZimmButton
            key={String(value.value)}
            // Selected reads as a primary action (dark fill, inverse label), unselected as an
            // outlined chip. `size="medium"` already supplies the Figma chip metrics from
            // tokens — 40px height, 20px inline padding, 12px/500 uppercase type — so only
            // the chip width and the lighter border need stating here.
            variant={isSelected ? 'primary' : 'secondary'}
            size="medium"
            label={value.label}
            // Visible text is just the size ("0"); the announced name needs the action.
            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
            role="checkbox"
            ariaChecked={isSelected}
            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
            sx={{
              // Floor, not a fixed width — a longer label than Figma anticipated grows its
              // own chip rather than being clipped. flexShrink 0 stops a crowded row from
              // squeezing chips below the spec width.
              minWidth: CHIP_MIN_WIDTH,
              flexShrink: 0,
              // ZimmButton's `secondary` uses a black border; the filter chip keeps the
              // lighter border/secondary grey from the Figma spec instead.
              ...(isSelected
                ? {}
                : {
                    borderColor: 'var(--zimm-color-border-secondary)',
                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
                  }),
            }}
          />
        );
      })}
    </Flex>
  );
};

/**
 * SFCC-847 — the Size facet's chip row, plus sub-group headings (e.g. Clothing/Accessories/
 * Shoes) when SFCC returns c_size as nested groups — the same nesting
 * `flattenRefinementValues` (overrides/app/utils/refinementValues.ts) already anticipates. A
 * flat (ungrouped) c_size refinement renders as a single ungrouped row.
 *
 * Grouping depends entirely on the shape SFCC sends: the API currently returns c_size flat, so
 * the ungrouped branch is what renders today. Producing the grouped design is BM configuration
 * (nested parent values), not a front-end change.
 *
 * @param props see ZimmSizeRefinementsProps
 */
export const ZimmSizeRefinements = ({ filter, toggleFilter, selectedFilters }: ZimmSizeRefinementsProps) => {
  const groups = filter.values ?? [];
  const isNested = groups.some((group) => group.values && group.values.length > 0);

  if (!isNested) {
    return <SizeChipRow filter={filter} toggleFilter={toggleFilter} selectedFilters={selectedFilters} />;
  }

  return (
    <Stack sx={{ gap: 'var(--zimm-scale-m)' }}>
      {groups.map((group) => (
        <Box key={String(group.value)}>
          {/* Sub-group heading (Clothing / Accessories / Shoes). `textStyle="body2Strong"`
              matches the design system's 14/18 medium letterSpacing entry; the earlier
              `fontStyle="italic"` was speculative and had no Figma reference (audited
              2026-09-16). */}
          <Text textStyle="body2Strong" marginBottom="var(--zimm-scale-xs)">
            {group.label}
          </Text>
          <SizeChipRow
            filter={{ attributeId: filter.attributeId, values: group.values }}
            toggleFilter={toggleFilter}
            selectedFilters={selectedFilters}
          />
        </Box>
      ))}
    </Stack>
  );
};

