import React from 'react';
import {
  Accordion,
  AccordionItem,
  AccordionButton,
  AccordionPanel,
  chakra,
  useMultiStyleConfig,
} from '@chakra-ui/react';
import { ChevronDownIcon, ChevronUpIcon } from 'app/components/icons';

const ZIMM_ACCORDION_RECIPE = 'ZimmAccordion';

export type ZimmAccordionItem = {
  /** Stable identifier — matches `defaultExpandedId` and acts as the React key. */
  id: string;
  /**
   * Group label shown in the header. Rendered uppercase via the `textStyle="productNames"`
   * design-system entry (see typography.ts), so callers pass Title Case ("Colour", not
   * "COLOUR") — this keeps i18n content faithful.
   */
  label: string;
  /**
   * Facet UI rendered inside the panel when expanded. SFCC-847 stops at the group
   * container — the real facet content (radio buttons, colour swatches, size chips, etc.)
   * is SFCC-108's scope.
   */
  content: React.ReactNode;
  /**
   * Optional content rendered directly under the header regardless of expanded state — use
   * for a compact summary the shopper needs to see at a glance without expanding the
   * accordion (e.g. the current selection chips for a filter facet). Rendered outside
   * Chakra's AccordionPanel, so it does not participate in the expand/collapse animation
   * and is not gated by aria-expanded. Leave undefined for accordions with no summary.
   */
  alwaysVisibleContent?: React.ReactNode;
};

type ZimmAccordionProps = {
  items: ZimmAccordionItem[];
  /**
   * Which item is open on first render. Uncontrolled — the user can toggle from here on
   * without informing the parent.
   */
  defaultExpandedId?: string;
};

/**
 * Single-open accordion group — a Zimmermann-styled wrapper around Chakra's Accordion
 * primitive. Delivers SFCC-847's accordion behaviour: only one item expanded at a time
 * (matches AC #5 and the DS 2026 Figma audited 2026-09-16, node
 * wPiWmZZOVKnrENUWk2XWWm/40003890:151742 which shows exactly one accordion expanded),
 * expanding a new item collapses the previously expanded one, and each header exposes
 * `aria-expanded` reflecting its state (unchanged from Chakra's own `AccordionButton`).
 *
 * The chevron swaps ChevronDown (collapsed) ↔ ChevronUp (expanded) using the render-prop
 * form of `AccordionItem`. A CSS-only 180° rotation on a single glyph could animate
 * between them, but Zimmermann's own chevron pair (icons/zimm.tsx nodes 40002082:49961 and
 * 40002128:29217) are drawn as distinct shapes — swapping is faithful, rotating isn't.
 *
 * @param props see ZimmAccordionProps
 */
export const ZimmAccordion = ({ items, defaultExpandedId }: ZimmAccordionProps) => {
  const styles = useMultiStyleConfig(ZIMM_ACCORDION_RECIPE, {});
  // `findIndex` returns -1 when the id isn't in `items`. Chakra's `defaultIndex={-1}` logs a
  // "out of range" warning at dev-time; coercing to `undefined` instead falls back to
  // Chakra's own default (nothing expanded).
  const initialIndex = items.findIndex((item) => item.id === defaultExpandedId);
  const defaultIndex = initialIndex >= 0 ? initialIndex : undefined;

  return (
    <Accordion allowToggle defaultIndex={defaultIndex} sx={styles.root}>
      {items.map((item) => (
        <AccordionItem key={item.id} sx={styles.item}>
          {({ isExpanded }) => (
            <>
