      [`@media (min-width: ${breakpoints.md})`]: {
        flexDirection: 'row',
        // Equal-width children — CLEAR/APPLY split 50/50.
        '& > *': {
          flex: '1 1 0',
          width: 'auto',
          minWidth: 0,
        },
      },
    },
  },
};
